Generate Python code that implements a factory and registry pattern for Python classes, allowing for registration and retrieval of classes using a centralized registry, using the following code:
```
from typing import TypeVar, Type

class Registry:
   _registry: dict[str, Type] = {}

   def register(cls: Type) -> None:
       """Register a class in the registry."""
       Registry._registry[cls.__name__] = cls

   def get(name: str) -> Type:
       """Retrieve a class from the registry."""
       return Registry._registry[name]

class Factory:
   def __init__(self, name: str):
       self.name = name

   def create() -> object:
       """Create an instance of the class specified by the factory's name."""
       return Registry.get(self.name)()
```

